using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Diagnostics;
using System.Threading;
using System.Windows.Forms;
using System.Collections.Generic;
class Uninstaller {
 static string Self=Assembly.GetExecutingAssembly().Location;
 static void NoLinks(string path){for(string p=Path.GetFullPath(path);!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((Directory.Exists(p)||File.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException(Language.T("Les liens et jonctions ne sont pas acceptes.", "Links and junctions are not supported."));}
 static string[] Validate(string folder){folder=Path.GetFullPath(folder).TrimEnd('\\');NoLinks(folder);if(folder==Path.GetPathRoot(folder).TrimEnd('\\'))throw new IOException(Language.T("Une racine de disque ne peut pas etre desinstallee.", "A drive root cannot be uninstalled."));string state=Path.Combine(folder,".semperfi-install.txt");NoLinks(state);string[] info=File.ReadAllLines(state);Guid id;if(info.Length!=5||(info[0]!="SemperFi-0.6"&&info[0]!="SemperFi-0.7"&&info[0]!="SemperFi-0.8")||!Guid.TryParseExact(info[1],"N",out id)||!String.Equals(info[2],folder,StringComparison.OrdinalIgnoreCase))throw new IOException(Language.T("Installation non reconnue ou deplacee. Le dossier doit rester a son emplacement d'installation.", "Installation not recognized or moved. Keep the folder at its original installation location."));foreach(var process in Process.GetProcessesByName("SF")){try{if(String.Equals(process.MainModule.FileName,Path.Combine(folder,"SF.EXE"),StringComparison.OrdinalIgnoreCase))throw new IOException(Language.T("Fermez Semper Fi avant la desinstallation.", "Close Semper Fi before uninstalling."));}catch(System.ComponentModel.Win32Exception){throw new IOException(Language.T("Un jeu SF est ouvert ; fermez-le avant la desinstallation.", "An SF game is running; close it before uninstalling."));}}return info;}
 static bool Saved(string name){return name.Equals("PREFS.DAT",StringComparison.OrdinalIgnoreCase)||name.StartsWith("SCEN\\",StringComparison.OrdinalIgnoreCase)||name.StartsWith("CAMPAIGN\\",StringComparison.OrdinalIgnoreCase);}
 static string Resolve(string folder,string relative){if(Path.IsPathRooted(relative)||relative.Split('\\','/').Any(s=>s==".."||s=="."||s==""))throw new IOException(Language.T("Chemin invalide.", "Invalid path."));string full=Path.GetFullPath(Path.Combine(folder,relative));if(!full.StartsWith(folder+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException(Language.T("Chemin hors installation.", "Path outside the installation."));NoLinks(full);return full;}
 static List<string> Plan(string folder,bool keep){var files=new List<string>();using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.tsv"))using(var reader=new StreamReader(stream)){foreach(string line in reader.ReadToEnd().Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){string name=line.Split('\t')[0];if(!keep||!Saved(name))files.Add(Resolve(folder,name));}}
  foreach(string name in new[]{Language.FileName,"save.log","ddraw.dll","DDrawCompat-SF.ini","DDrawCompat-SF.log","DDrawCompat-SF.dmp","DDrawCompat-LICENSE.txt","Jouer.cmd","INSTALLATION.txt","COMPATIBILITE.txt","DESINSTALLATION.txt","installation.log","source-files.tsv","installed-files.tsv","compat-backup\\SF.original.exe","compat-backup\\SF.before-music-v07.exe","Desinstaller.exe"})files.Add(Resolve(folder,name));
  if(!keep){foreach(string sub in new[]{"SCEN","CAMPAIGN"}){string directory=Resolve(folder,sub);if(Directory.Exists(directory))Walk(directory,files);}}
  return files.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
 }
 static void Walk(string folder,List<string> files){NoLinks(folder);foreach(string file in Directory.GetFiles(folder)){NoLinks(file);files.Add(file);}foreach(string child in Directory.GetDirectories(folder))Walk(child,files);}
 static void EmptyDirectories(string folder){NoLinks(folder);foreach(string child in Directory.GetDirectories(folder)){if((File.GetAttributes(child)&FileAttributes.ReparsePoint)!=0)continue;EmptyDirectories(child);}if(!Directory.EnumerateFileSystemEntries(folder).Any())Directory.Delete(folder,false);}
 static void Remove(string folder,bool keep){string[] state=Validate(folder);List<string> plan=Plan(folder,keep);
  string shortcutPath=state[3];if(File.Exists(shortcutPath)){NoLinks(shortcutPath);object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object shortcut=null;try{shortcut=shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{shortcutPath});string target=(string)shortcut.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,shortcut,null);if(String.Equals(target,Path.Combine(folder,"SF.EXE"),StringComparison.OrdinalIgnoreCase))File.Delete(shortcutPath);}finally{if(shortcut!=null)Marshal.FinalReleaseComObject(shortcut);Marshal.FinalReleaseComObject(shell);}}
  foreach(string file in plan)if(File.Exists(file)){for(int attempt=0;;attempt++){try{File.SetAttributes(file,FileAttributes.Normal);File.Delete(file);break;}catch(IOException){if(attempt>=20)throw;Thread.Sleep(250);}}}
  InstallSupport.Unregister(folder,state[1],state[4]);
  File.Delete(Resolve(folder,".semperfi-install.txt"));
  EmptyDirectories(folder);
 }
 static string Q(string value){return InstallSupport.Quote(value);}
 static void CleanupWorker(){string directory=Path.GetDirectoryName(Self),temp=Path.GetFullPath(Path.GetTempPath());if(!directory.StartsWith(temp,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(directory).StartsWith("SemperFi-uninstall-"))return;string script="Wait-Process -Id "+Process.GetCurrentProcess().Id+" -ErrorAction SilentlyContinue; Remove-Item -LiteralPath '"+Self.Replace("'","''")+"' -Force; Remove-Item -LiteralPath '"+directory.Replace("'","''")+"' -ErrorAction SilentlyContinue";var start=new ProcessStartInfo("powershell.exe","-NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script)));start.UseShellExecute=false;start.CreateNoWindow=true;Process.Start(start);}
 [STAThread] static int Main(string[] args){bool worker=false;try{
  bool explicitLanguage=Array.IndexOf(args,"--lang")>=0; args=Language.Parse(args); worker=args.Length==4&&args[0]=="--worker";
  if(!explicitLanguage)Language.Load(args.Length>=2?args[1]:Path.GetDirectoryName(Self));
  if(worker){string folder=Path.GetFullPath(args[1]).TrimEnd('\\');if(Validate(folder)[1]!=args[3])throw new IOException(Language.T("Identifiant d'installation incorrect.", "Incorrect installation identifier."));Thread.Sleep(500);Remove(folder,args[2]=="keep");MessageBox.Show(args[2]=="keep"?Language.T("Jeu desinstalle. Sauvegardes et preferences conservees dans :\n", "Game uninstalled. Saved games and preferences retained in:\n")+folder:Language.T("Jeu desinstalle. Les autres fichiers personnels eventuels sont conserves.", "Game uninstalled. Any other personal files have been retained."),"Semper Fi");return 0;}
  if(args.Length==3&&args[0]=="--uninstall"){string folder=Path.GetFullPath(args[1]).TrimEnd('\\');if(args[2]!="--keep-saves"&&args[2]!="--delete-saves")throw new IOException(Language.T("Option invalide.", "Invalid option."));if(Self.StartsWith(folder+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException(Language.T("Ce mode doit etre lance depuis un autre dossier.", "This mode must be run from a different folder."));if(InstallSupport.Protected(folder)&&!InstallSupport.Administrator)return InstallSupport.Elevate(Self,"--uninstall "+Q(folder)+" "+args[2]+Language.Arguments);Remove(folder,args[2]=="--keep-saves");return 0;}
  if(args.Length>0)throw new ArgumentException("Usage: --uninstall FOLDER --keep-saves|--delete-saves [--lang fr|en]");
  string root=Path.GetDirectoryName(Self);string[] state=Validate(root);Application.EnableVisualStyles();
  var form=new Form();form.Text=Language.T("Desinstaller Semper Fi", "Uninstall Semper Fi");form.ClientSize=new System.Drawing.Size(540,205);form.FormBorderStyle=FormBorderStyle.FixedDialog;form.MaximizeBox=false;form.StartPosition=FormStartPosition.CenterScreen;
  var label=new Label();label.Text=Language.T("Retirer le jeu et son raccourci du Bureau.\nFermez le jeu avant de continuer.", "Remove the game and its desktop shortcut.\nClose the game before continuing.");label.SetBounds(18,18,500,48);form.Controls.Add(label);
  var keep=new CheckBox();keep.Text=Language.T("Conserver mes sauvegardes et mes preferences", "Keep my saved games and preferences");keep.Checked=true;keep.SetBounds(18,80,500,28);form.Controls.Add(keep);
  var note=new Label();note.Text=Language.T("Elles restent dans SCEN, CAMPAIGN et PREFS.DAT.\nLes autres fichiers personnels restent conserves.", "They remain in SCEN, CAMPAIGN and PREFS.DAT.\nOther personal files are retained.");note.SetBounds(18,112,500,40);form.Controls.Add(note);
  var remove=new Button();remove.Text=Language.T("Desinstaller", "Uninstall");remove.SetBounds(18,163,130,28);form.Controls.Add(remove);var cancel=new Button();cancel.Text=Language.T("Annuler", "Cancel");cancel.SetBounds(160,163,110,28);form.Controls.Add(cancel);cancel.Click+=(s,e)=>form.Close();
  remove.Click+=(s,e)=>{try{if(!keep.Checked&&MessageBox.Show(Language.T("Supprimer egalement les sauvegardes et preferences de cette installation ?", "Also delete this installation's saved games and preferences?"),Language.T("Suppression des sauvegardes", "Delete saved games"),MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;Plan(root,keep.Checked);string temp=Path.Combine(Path.GetTempPath(),"SemperFi-uninstall-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string child=Path.Combine(temp,"Desinstaller.exe");File.Copy(Self,child);Process.Start(new ProcessStartInfo(child,"--worker "+Q(root)+" "+(keep.Checked?"keep":"delete")+" "+state[1]+Language.Arguments){UseShellExecute=true,Verb=InstallSupport.Protected(root)&&!InstallSupport.Administrator?"runas":"open",WindowStyle=ProcessWindowStyle.Hidden});form.Close();}catch(Exception ex){MessageBox.Show(ex.Message,Language.T("Desinstallation interrompue", "Uninstall interrupted"));}};
  Application.Run(form);return 0;
 }catch(Exception ex){if(args.Length>0){try{File.WriteAllText(Path.Combine(Path.GetDirectoryName(Self),"uninstall-error.txt"),ex.ToString());}catch{}if(worker)MessageBox.Show(ex.Message,Language.T("Desinstallation interrompue", "Uninstall interrupted"));return 1;}MessageBox.Show(ex.Message,Language.T("Desinstallation interrompue", "Uninstall interrupted"));return 1;}finally{if(worker)CleanupWorker();}}
}
